sed -i 's/^    }    fun openPdf/    }\n\n    fun generateAnalysisReportPdf(context: Context, analysisText: String): Uri? {\n        val pdfDocument = PdfDocument()\n        val pageWidth = 595\n        val pageHeight = 842\n        val margin = 50f\n        var pageNum = 1\n        var pageInfo = PdfDocument.PageInfo.Builder(pageWidth, pageHeight, pageNum).create()\n        var page = pdfDocument.startPage(pageInfo)\n        var canvas = page.canvas\n        \n        val textPaint = android.text.TextPaint().apply {\n            color = android.graphics.Color.BLACK\n            textSize = 12f\n            isAntiAlias = true\n        }\n        val titlePaint = android.text.TextPaint().apply {\n            color = android.graphics.Color.BLACK\n            textSize = 16f\n            isFakeBoldText = true\n            isAntiAlias = true\n        }\n\n        val contentWidth = (pageWidth - 2 * margin).toInt()\n        val lines = analysisText.split("\\n")\n        var currentY = 50f\n        \n        canvas.drawText("ОТЧЕТ ПО ПРАВОВОМУ АНАЛИЗУ", margin, currentY, titlePaint)\n        currentY += 20f\n        val sdf = java.text.SimpleDateFormat("dd.MM.yyyy HH:mm", java.util.Locale.getDefault())\n        canvas.drawText("Дата генерации: ${sdf.format(java.util.Date())}", margin, currentY, textPaint)\n        currentY += 30f\n        \n        for (paragraph in lines) {\n            if (paragraph.isBlank()) {\n                currentY += textPaint.textSize\n                continue\n            }\n            val staticLayout = android.text.StaticLayout(\n                paragraph, textPaint, contentWidth, android.text.Layout.Alignment.ALIGN_NORMAL, 1.0f, 0.0f, false\n            )\n            if (currentY + staticLayout.height > pageHeight - margin) {\n                pdfDocument.finishPage(page)\n                pageNum++\n                pageInfo = PdfDocument.PageInfo.Builder(pageWidth, pageHeight, pageNum).create()\n                page = pdfDocument.startPage(pageInfo)\n                canvas = page.canvas\n                currentY = margin\n            }\n            canvas.save()\n            canvas.translate(margin, currentY)\n            staticLayout.draw(canvas)\n            canvas.restore()\n            currentY += staticLayout.height + 5f\n        }\n\n        pdfDocument.finishPage(page)\n        val file = File(context.cacheDir, "Analysis_Report_${System.currentTimeMillis()}.pdf")\n        return try {\n            pdfDocument.writeTo(FileOutputStream(file))\n            pdfDocument.close()\n            FileProvider.getUriForFile(context, "${context.packageName}.fileprovider", file)\n        } catch (e: Exception) {\n            e.printStackTrace()\n            pdfDocument.close()\n            null\n        }\n    }\n\n    fun openPdf/g' app/src/main/java/com/example/utils/DocumentGenerator.kt
